function AssetsPage({ assets, addAsset, removeAssets }: { assets: Asset[]; addAsset: (asset: Asset) => void; removeAssets: (ids: string[]) => void }) {
  const [view, setView] = useState<"list" | "asset-create" | "family-create" | "detail">("list");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState(initialAssets[0].id);
  const [createOpen, setCreateOpen] = useState(false);
  const [grid, setGrid] = useState(true);
  const [label, setLabel] = useState("");
  const [code, setCode] = useState("");
  const [moreOpen, setMoreOpen] = useState(false);
  const [query, setQuery] = useState(""); const [page, setPage] = useState(1);
  const [filters, setFilters] = useState<Record<string, string>>({ code: "All", label: "All", complete: "All", usage: "All", created: "All", updated: "All" });
  const selected = assets.find(asset => asset.id === selectedId) ?? assets[0];
  const filterConfig: FilterConfig[] = [{ id: "code", label: "Asset code", options: ["All", ...assets.map(asset => asset.code)] }, { id: "label", label: "Asset label", options: ["All", ...assets.map(asset => asset.label)] }, { id: "complete", label: "Complete", options: ["All", "Complete", "Incomplete"] }, { id: "usage", label: "Usage status", options: ["All", "Used", "Unused"] }, { id: "created", label: "Created", options: ["All", "Today", "Earlier"] }, { id: "updated", label: "Updated", options: ["All", "Today", "Earlier"] }];
  const filteredAssets = assets.filter(asset => `${asset.label} ${asset.code}`.toLowerCase().includes(query.toLowerCase()) && (filters.code === "All" || asset.code === filters.code) && (filters.label === "All" || asset.label === filters.label) && (filters.complete === "All" || (filters.complete === "Complete" ? Boolean(asset.code && asset.label) : !asset.code || !asset.label)) && (filters.usage === "All" || (filters.usage === "Used" ? Boolean(asset.productId) : !asset.productId)) && (filters.created === "All" || (filters.created === "Today" ? Boolean(asset.createdAt) : !asset.createdAt)) && (filters.updated === "All" || (filters.updated === "Today" ? Boolean(asset.updatedAt) : !asset.updatedAt))); const pageAssets = filteredAssets.slice((page - 1) * 12, page * 12);
  const toggle = (id: string) => setSelectedIds(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);
  const openOrToggle = (id: string) => { if (selectedIds.length) { toggle(id); return; } setSelectedId(id); setView("detail"); };
  const createAsset = () => { if (!label.trim() || !code.trim()) return; const asset = { id: "asset-" + code.trim().toLowerCase(), code: code.trim().toLowerCase(), label: label.trim(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; addAsset(asset); setSelectedId(asset.id); setLabel(""); setCode(""); setView("detail"); };
  const deleteSelected = () => { if (window.confirm(`Delete ${selectedIds.length} selected asset${selectedIds.length > 1 ? "s" : ""}?`)) { removeAssets(selectedIds); setSelectedIds([]); } };
  const deleteCurrent = () => { removeAssets([selected.id]); setView("list"); };

  if (view === "asset-create" || view === "family-create") return <main className="relative grid min-h-screen flex-1 place-items-center"><button onClick={() => setView("list")} className="absolute left-12 top-10"><X /></button><form onSubmit={event => { event.preventDefault(); if (view === "asset-create") createAsset(); else setView("list"); }} className="w-[580px] border-l border-[#9d4ed1] pl-12"><p className="text-sm text-[#9d4ed1]">ASSET FAMILIES</p><h1 className="mb-10 mt-3 text-4xl font-light">{view === "asset-create" ? "Add new asset in imported assets" : "Create a new asset family"}</h1><label className="mb-6 block text-[#58708e]">Label<input required value={label} onChange={event => setLabel(event.target.value)} className="mt-2 h-13 w-full border border-[#bdc9da] px-4 outline-none" /></label><label className="mb-6 block text-[#58708e]">Code <i>(required)</i><input required value={code} onChange={event => setCode(event.target.value)} className="mt-2 h-13 w-full border border-[#bdc9da] px-4 outline-none" /></label>{view === "asset-create" && <label className="mb-6 flex items-center gap-3"><input type="checkbox" /> Create another asset</label>}<button className="rounded-full bg-[#61b477] px-6 py-2.5 font-semibold text-white">SAVE</button></form></main>;

  if (view === "detail" && selected) return <main className="min-w-0 flex-1"><div className="px-12 py-8"><div className="mb-10 flex gap-6"><div className="grid h-44 w-44 place-items-center border border-[#cbd4e1] bg-[#f7f9fc]"><ImageIcon size={64} className="text-[#9d4ed1]" /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-6"><p className="text-sm tracking-wide text-[#58708e]">ASSET FAMILIES / <button onClick={() => setView("list")} className="text-[#317ec1] hover:underline">IMPORTED ASSETS</button> / {selected.code.toUpperCase()}</p><div className="flex shrink-0 items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-full bg-[#337bb8] font-semibold text-white">TB</div><button aria-label="Notifications" className="grid h-10 w-10 place-items-center rounded-full border border-[#d5dbe7]"><Bell size={18} /></button><div className="relative"><button onClick={() => setMoreOpen(value => !value)} className="px-3 text-2xl text-[#58708e]">…</button>{moreOpen && <div className="absolute right-0 top-10 z-10 w-52 border border-[#d5dbe7] bg-white p-4 shadow-lg"><p className="mb-3 text-xs text-[#9d4ed1]">OTHER ACTIONS</p><button onClick={deleteCurrent} className="text-[#c6544e]">Delete</button></div>}</div><button className="rounded-full bg-[#61b477] px-6 py-2.5 text-sm font-semibold text-white">SAVE</button></div></div><h1 className="mt-5 text-[36px] font-light text-[#9650d0]">{selected.label}</h1><p className="mt-5">Channel: <span className="text-[#9d4ed1]">Ecommerce</span><span className="ml-6">Locale: 🇺🇸 <span className="text-[#9d4ed1]">English (United States)</span></span></p><p className="mt-5 text-sm text-[#58708e]">Created: 11/18/2026, 02:42 AM <span className="mx-3">|</span> Updated: 11/18/2026, 02:42 AM</p></div></div><div className="grid gap-12 xl:grid-cols-2"><section><h2 className="border-b border-[#173d61] pb-3 text-xl">EDIT ASSET</h2><label className="mt-7 block text-[#58708e]">Label<input defaultValue={selected.label} className="mt-2 h-13 w-full border border-[#bdc9da] px-4 outline-none" /></label><div className="mt-7"><p className="mb-2 text-[#58708e]">Media</p><div className="grid h-24 place-items-center border border-[#bdc9da] text-[#58708e]">Drag and drop to upload or click here</div></div><div className="mt-7 border border-[#bdc9da] p-4 text-[#317ec1]">https://media.nexusoms.local/{selected.code}.jpg</div></section><section className="border-l border-[#9d4ed1] pl-12"><h2 className="border-b border-[#173d61] pb-3 text-xl">MEDIA PREVIEW</h2><div className="mt-6 grid min-h-[440px] place-items-center bg-[#f7f9fc]"><ImageIcon size={120} className="text-[#9d4ed1]" /><p className="-mt-40 text-[#58708e]">{selected.label}</p></div></section></div></div></main>;

  return <div className="flex min-h-screen flex-1"><aside className="w-[280px] shrink-0 border-r border-[#d5dbe7] bg-[#f8faff] p-9"><p className="mb-8 text-sm text-[#91a1b8]">ASSET NAVIGATION</p><p className="mb-2 text-sm text-[#91a1b8]">ASSET FAMILIES</p><p className="mb-10">Imported Assets <ChevronDown className="inline" size={16} /></p><FilterPanel filters={filterConfig} values={filters} onChange={(id, value) => { setFilters(current => ({ ...current, [id]: value })); setPage(1); }} /></aside><main className="min-w-0 flex-1"><header className="flex h-24 items-center justify-end gap-3 border-b border-[#d5dbe7] px-10"><div className="grid h-10 w-10 place-items-center rounded-full bg-[#337bb8] font-semibold text-white">TB</div><button aria-label="Notifications" className="grid h-10 w-10 place-items-center rounded-full border border-[#d5dbe7]"><Bell size={18} /></button><button className="rounded-full border border-[#58a4e8] px-5 py-2 text-sm text-[#317ec1]">EDIT FAMILY</button><div className="relative"><button onClick={() => setCreateOpen(value => !value)} className="rounded-full bg-[#61b477] px-6 py-2.5 text-sm font-semibold text-white">CREATE <ChevronDown className="inline" size={16} /></button>{createOpen && <div className="absolute right-0 top-12 z-10 w-56 border border-[#d5dbe7] bg-white p-2 shadow-lg"><button onClick={() => setView("asset-create")} className="block w-full px-3 py-3 text-left hover:bg-[#f7f9fc]">Create an asset</button><button disabled className="block w-full px-3 py-3 text-left text-[#91a1b8]">Upload assets 🔒</button><button onClick={() => setView("family-create")} className="block w-full px-3 py-3 text-left hover:bg-[#f7f9fc]">Create an asset family</button></div>}</div></header><section className="min-w-0 flex-1 px-12 py-10"><p className="text-sm tracking-wide text-[#58708e]">ASSET FAMILIES / IMPORTED ASSETS</p><h1 className="mt-6 text-[36px] font-light text-[#9650d0]">{filteredAssets.length} results</h1><div className="mt-8 flex items-center gap-4 border-b border-[#9eb0c5] pb-3"><Search size={22} className="text-[#607b9b]" /><input value={query} onChange={event => { setQuery(event.target.value); setPage(1); }} placeholder="Search on label, code and text attributes" className="min-w-0 flex-1 bg-transparent text-sm outline-none" /><span className="text-sm text-[#9d4ed1]">{filteredAssets.length} results</span><button onClick={() => setGrid(true)} className={grid ? "bg-[#eee1f6] p-2 text-[#9a55cf]" : "p-2"}><Grid2X2 size={22} /></button><button onClick={() => setGrid(false)} className={!grid ? "bg-[#eee1f6] p-2 text-[#9a55cf]" : "p-2"}><List size={22} /></button></div><p className="mt-4 bg-[#f1f7fd] p-4 text-sm text-[#58708e]">Usage status is unknown. Run an analysis later to identify which assets are used or unused in your catalog.</p><div className={grid ? "mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4" : "mt-6 space-y-3"}>{pageAssets.map(asset => <article key={asset.id} onClick={() => openOrToggle(asset.id)} className={`${grid ? "cursor-pointer border p-3" : "flex cursor-pointer items-center gap-4 border p-3"} ${selectedIds.includes(asset.id) ? "border-[#5b9bd5] bg-[#f1f7fd]" : "border-[#cbd4e1] hover:border-[#9d4ed1]"}`}><div className={grid ? "grid aspect-square place-items-center bg-[#f7f9fc]" : "grid h-20 w-20 place-items-center bg-[#f7f9fc]"}><ImageIcon size={grid ? 58 : 34} className="text-[#7d96ae]" /></div><div className={grid ? "mt-3 flex items-center gap-2" : "flex items-center gap-2"}><input aria-label={"Select " + asset.label} type="checkbox" checked={selectedIds.includes(asset.id)} onClick={event => event.stopPropagation()} onChange={() => toggle(asset.id)} /><span className="truncate text-sm">{asset.label}</span></div></article>)}</div><Pagination page={page} totalItems={filteredAssets.length} pageSize={12} onChange={setPage} /></section>{selectedIds.length > 0 && <div className="fixed bottom-0 left-[104px] right-0 flex items-center gap-4 border-t border-[#d5dbe7] bg-white p-5 shadow-lg"><span className="font-medium">{selectedIds.length} ASSETS SELECTED</span><button disabled={selectedIds.length !== 1} onClick={() => { setSelectedId(selectedIds[0]); setSelectedIds([]); setView("detail"); }} className="rounded-full bg-[#5b9bd5] px-5 py-2 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40">EDIT</button><button onClick={deleteSelected} className="rounded-full bg-[#d85c4e] px-5 py-2 text-sm font-semibold text-white">DELETE</button></div>}</main></div>;
}

